use super::*;
use std::fs;
use crate::local_database::joint_archive::tests::genuine_import_owner_fixture;
use std::path::PathBuf;
async fn fixture(length:usize)->(PathBuf,Owner,Value,Value){let(root,selection,request,context,result)=genuine_import_owner_fixture(length).await;let owner=Owner::capture(selection,"none",request,context.clone()).unwrap();(root,owner,context,result)}
#[tokio::test]async fn genuine_joint_owner_reads_exact_reference_and_original_raw_provenance(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,owner,current,result)=fixture(196608).await;let raw=result["imported_provenance"].clone();assert_eq!(result["reference_changes"][0]["offset_unit"],"utf16_code_units");owner.with_read(current,|reader|{let mut bytes=Vec::new();assert_eq!(reader.copy_exact(&mut bytes)?,196608);assert_eq!(bytes,vec![7;196608]);Ok(())}).await.unwrap();let db=SqlitePoolOptions::new().connect_with(SqliteConnectOptions::new().filename(root.join("new-vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();let original:String=sqlx::query_scalar("SELECT result_json FROM native_archive_import_receipts").fetch_one(&db).await.unwrap();assert_eq!(serde_json::from_str::<Value>(&original).unwrap()["imported_provenance"],raw);db.close().await;fs::remove_dir_all(root).unwrap();}
#[tokio::test]async fn removed_reference_asset_page_and_wrong_context_refuse(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());for change in ["reference","asset","page","context"]{let(root,owner,current,_)=fixture(7).await;if change=="context"{let mut wrong=current.clone();wrong["sessionId"]=json!("foreign");assert!(owner.with_read(wrong,|_|Ok(())).await.unwrap_err().contains("context changed"));}else{let db=SqlitePoolOptions::new().connect_with(SqliteConnectOptions::new().filename(root.join("new-vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();let mut snapshot=read_snapshot_from_pool(&db,"none").await.unwrap().unwrap();match change{"reference"=>snapshot["documents"][0]["content"]=json!("reference removed"),"asset"=>snapshot["assets"]=json!([]),_=>snapshot["documents"]=json!([])}let mut tx=db.begin().await.unwrap();write_snapshot_in_tx(&mut tx,"none",&snapshot).await.unwrap();tx.commit().await.unwrap();db.close().await;assert!(owner.with_read(current,|_|Ok(())).await.is_err());}fs::remove_dir_all(root).unwrap();}}
#[tokio::test]async fn foreign_equal_content_destination_alias_manifest_and_directory_refuse(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());for change in ["destination","alias","manifest","directory"]{let(root,owner,current,result)=fixture(7).await;let operation=root.join("new-vault/.starlane/archive-imports").join(&owner.request.operation);let target=match change{"destination"=>PathBuf::from(result["candidate"]["assets"][0]["vault_path"].as_str().unwrap()),"alias"=>operation.join("asset-0"),"manifest"=>operation.join("manifest.json"),_=>operation.clone()};let retained=target.with_extension("original");fs::rename(&target,&retained).unwrap();if change=="directory"{fs::create_dir(&target).unwrap();use std::os::unix::fs::PermissionsExt;fs::set_permissions(&target,fs::Permissions::from_mode(0o700)).unwrap();for name in ["asset-0","manifest.json"]{fs::copy(retained.join(name),target.join(name)).unwrap();}}else{fs::copy(&retained,&target).unwrap();}assert!(owner.with_read(current,|_|Ok(())).await.is_err(),"foreign {change} must not own equal bytes");fs::remove_dir_all(root).unwrap();}}
#[tokio::test]async fn declared_session_sql_writer_and_stream_change_refuse(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,owner,current,result)=fixture(196608).await;let database=root.join("new-vault/.starlane/starlane-notes.sqlite3");let target=PathBuf::from(result["candidate"]["assets"][0]["vault_path"].as_str().unwrap());let failure=owner.with_read(current,move|reader|{let response=std::process::Command::new("python3").args(["-c","import sqlite3,sys; c=sqlite3.connect(sys.argv[1],timeout=.02);\ntry: c.execute(\"UPDATE local_vault_metadata SET value='foreign' WHERE key='canonical_revision'\"); c.commit(); print('CHANGED')\nexcept sqlite3.OperationalError: print('LOCKED')\nfinally: c.close()"] ).arg(database).output().map_err(err)?;assert!(response.status.success());assert_eq!(String::from_utf8(response.stdout).unwrap().trim(),"LOCKED");struct Changed{path:PathBuf,once:bool}impl Write for Changed{fn write(&mut self,b:&[u8])->std::io::Result<usize>{if !self.once{self.once=true;let held=self.path.with_extension("held");fs::rename(&self.path,&held)?;fs::copy(held,&self.path)?;}Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}reader.copy_exact(&mut Changed{path:target,once:false}).map(|_|())}).await.unwrap_err();assert!(failure.contains("custody")||failure.contains("inode"));fs::remove_dir_all(root).unwrap();}
#[tokio::test]#[ignore="fresh separate process import owner worker"]async fn restart_worker(){let path=std::env::var("STARLANE_ARCHIVE_IMPORT_OWNER_FIXTURE").expect("private fixture required");let fixture:Value=serde_json::from_slice(&fs::read(path).unwrap()).unwrap();let root=PathBuf::from(fixture["vault"].as_str().unwrap());let selection=vault::SnapshotRequestBinding::capture_at(PathBuf::from(fixture["settings"].as_str().unwrap()),root,"none").unwrap();let request:Request=serde_json::from_value(fixture["request"].clone()).unwrap();let context=fixture["context"].clone();let owner=Owner::capture(selection,"none",request,context.clone()).unwrap();owner.with_read(context,|reader|{let mut bytes=Vec::new();reader.copy_exact(&mut bytes)?;assert_eq!(bytes,vec![7;196608]);println!("FRESH_PROCESS_GENUINE_IMPORTED_OWNER_READ_PASS");Ok(())}).await.unwrap();}
#[tokio::test]async fn genuine_import_reader_restarts_with_original_destination_authority(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,owner,current,_)=fixture(196608).await;let path=root.join("worker.json");fs::write(&path,json!({"vault":root.join("new-vault"),"settings":root.join("new-settings.json"),"request":owner.request,"context":current}).to_string()).unwrap();drop(owner);let result=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","local_database::attachment_download_owner::native_archive_import::tests::restart_worker","--ignored","--nocapture"]).env("STARLANE_ARCHIVE_IMPORT_OWNER_FIXTURE",path).output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stdout));assert!(String::from_utf8_lossy(&result.stdout).contains("FRESH_PROCESS_GENUINE_IMPORTED_OWNER_READ_PASS"));fs::remove_dir_all(root).unwrap();}
#[tokio::test]#[ignore="actual genuine source download/canonical archive/joint import/reader100MiB"]async fn actual_genuine_import_owner_100mib(){let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());let(root,owner,current,result)=fixture(104857600).await;let expected=result["candidate"]["assets"][0]["server_version_provenance"]["bytes_sha256"].as_str().unwrap().to_string();owner.with_read(current,move|reader|{struct Check{hash:Sha256,count:u64,max:usize}impl Write for Check{fn write(&mut self,b:&[u8])->std::io::Result<usize>{assert!(b.iter().all(|v|*v==7));self.hash.update(b);self.count+=b.len()as u64;self.max=self.max.max(b.len());Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}let mut check=Check{hash:Sha256::new(),count:0,max:0};assert_eq!(reader.copy_exact(&mut check)?,104857600);assert_eq!(check.count,104857600);assert_eq!(check.max,65536);assert_eq!(format!("{:x}",check.hash.finalize()),expected);println!("ACTUAL_SOURCE_CANONICAL_ZIP_JOINT_IMPORT_OWNER_100MIB_EXACT_RAW_HASH_ALL_BYTES_64K_PASS");Ok(())}).await.unwrap();fs::remove_dir_all(root).unwrap();}

#[test]fn parsed_markdown_reference_requires_exact_destination(){
 let url="asset://localhost/exact.bin";
 for body in [format!("![file]({url})"),format!("[file](<{url}> \"title\")"),format!("<{url}>"),format!("[file][owned]\n\n[owned]: {url}"),format!("> ![file]({url})")]{assert!(has_exact_markdown_reference(&body,url),"{body}");}
 for body in [url.to_string(),format!("prose {url}"),format!("`![file]({url})`"),format!("```\n![file]({url})\n```"),format!("    ![file]({url})"),format!("![file]({url}.foreign)"),format!("![file]({url}?foreign)"),format!("[label {url}](https://example.com)"),format!("[owned]: {url}"),format!("<img src=\"{url}\">"),format!("<!-- ![file]({url}) -->")]{assert!(!has_exact_markdown_reference(&body,url),"{body}");}
}
#[tokio::test]async fn interactive_current_reference_admission_is_distinct_from_owned_archive_capture(){
 let _g=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());
 let(root,owner,current,result)=fixture(7).await;
 let url=result["candidate"]["assets"][0]["url"].as_str().unwrap();
 let db=SqlitePoolOptions::new().connect_with(SqliteConnectOptions::new().filename(root.join("new-vault/.starlane/starlane-notes.sqlite3"))).await.unwrap();
 let original=read_snapshot_from_pool(&db,"none").await.unwrap().unwrap();
 for (body,cover,accepted) in [(url.to_string(),String::new(),false),(format!("`![x]({url})`"),String::new(),false),(format!("```\n![x]({url})\n```"),String::new(),false),(format!("![x]({url}.foreign)"),String::new(),false),(String::new(),format!("prefix{url}"),false),(String::new(),url.to_string(),true),(format!("![x]({url})"),String::new(),true),(format!("[x][ref]\n\n[ref]: {url}"),String::new(),true)]{
  let mut snapshot=original.clone();snapshot["documents"][0]["content"]=json!(body);snapshot["documents"][0]["cover_image"]=json!(cover);
  let mut tx=db.begin().await.unwrap();write_snapshot_in_tx(&mut tx,"none",&snapshot).await.unwrap();tx.commit().await.unwrap();
  assert_eq!(owner.clone().with_read(current.clone(),|_|Ok(())).await.is_ok(),accepted,"reader {body} {cover}");
  let revision:String=sqlx::query_scalar("SELECT value FROM local_vault_metadata WHERE key='canonical_revision'").fetch_one(&db).await.unwrap();
  let capture=native_archive_capture::Owner::capture(owner.selection.clone(),"none",&revision,current.clone()).unwrap();
  // Whole-vault portability retains genuinely owned canonical binaries even
  // when their current body reference is removed. This never changes serving.
  capture.with_capture(current.clone(),|capture|{assert_eq!(capture.binaries.len(),1);Ok(())}).await.unwrap();
 }
 db.close().await;fs::remove_dir_all(root).unwrap();
}
